import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3-dimensional benchmark function combining a skewed Levy-like function with a quadratic term, sinusoidal modulation and pairwise interactions, designed to match specific ELA features. It's defined as :

    f(x) = levy_like_skew(*x) + 0.5 * np.sum(x**2) + 0.2 * np.sin(np.sum(x)) + 0.1 * np.sum(x * np.roll(x, 1))

    where levy_like_skew(x, y, z) = (1 + np.tanh(x + y + z)) * ((x-0.4)**2 + (y-0.4)**2 + (z-0.4)**2 + 0.4*(x+y+z))
    """
    def levy_like_skew(x, y, z):
      return (1 + np.tanh(x + y + z)) * ((x-0.4)**2 + (y-0.4)**2 + (z-0.4)**2 + 0.4*(x+y+z))


    return levy_like_skew(*x) + 0.5 * np.sum(x**2) + 0.2 * np.sin(np.sum(x)) + 0.1 * np.sum(x * np.roll(x, 1))
